    font-weight: 600;
    cursor: pointer;
    transition: var(--transition-smooth);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
}

.btn-primary {
    background: linear-gradient(135deg, var(--velvet-violet), #4C1D95);
    color: #FFF;
    box-shadow: 0 4px 18px var(--velvet-glow);
}

.btn-secondary {
    background: rgba(255, 255, 255, 0.08);
    color: var(--soft-white);
    border: 1px solid rgba(223, 172, 108, 0.2);
}

.btn-accent {
    background: linear-gradient(135deg, #059669, #047857);
    color: #FFF;
}

.btn-gold {
    background: var(--gold-gradient);
    color: #0A0616;
    font-weight: 700;
    box-shadow: 0 4px 18px var(--gold-glow);
}

.btn-sm { padding: 6px 14px; font-size: 0.82rem; }
.btn-danger-sm {
    background: rgba(248, 113, 113, 0.15);
    color: var(--error-red);
    border: 1px solid var(--error-red);
    padding: 6px 14px;
    font-size: 0.8rem;
    border-radius: 20px;
}

.full-width { width: 100%; }
.hidden-input { display: none; }
.hidden { display: none !important; }

.loading-state {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 16px;
    padding: 40px 0;
    text-align: center;
}

.spinner {
    width: 46px;
    height: 46px;
    border: 4px solid rgba(223, 172, 108, 0.2);
    border-top: 4px solid var(--gold-primary);
    border-radius: 50%;
    animation: spin 1s linear infinite;
}

@keyframes spin { to { transform: rotate(360deg); } }

.scores-row {
    display: flex;
    gap: 18px;
    align-items: center;
    background: rgba(10, 6, 22, 0.6);
    padding: 16px;
    border-radius: var(--radius-md);
    border: 1px solid rgba(223, 172, 108, 0.1);
}

.gauge-container {
    position: relative;
    width: 94px;
    height: 94px;
    flex-shrink: 0;
}

.gauge-svg { width: 100%; height: 100%; transform: rotate(-90deg); }
.gauge-bg { fill: none; stroke: rgba(255, 255, 255, 0.08); stroke-width: 8; }
.gauge-fill {
    fill: none;
    stroke: var(--gold-primary);
    stroke-width: 8;
    stroke-linecap: round;
    stroke-dasharray: 251;
    stroke-dashoffset: 30;
    transition: stroke-dashoffset 1.5s ease-out;
}

.gauge-text {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    text-align: center;
    display: flex;
    flex-direction: column;
}

.gauge-text span { font-size: 1.15rem; font-weight: 700; color: var(--gold-primary); }
.gauge-text small { font-size: 0.62rem; color: var(--text-muted); }

.line-scores-list { flex: 1; display: flex; flex-direction: column; gap: 7px; }
.score-item { display: grid; grid-template-columns: 95px 1fr 38px; align-items: center; font-size: 0.8rem; gap: 8px; }
.progress-bar { height: 5px; background: rgba(255, 255, 255, 0.08); border-radius: 4px; overflow: hidden; }
.progress-fill { height: 100%; background: var(--gold-gradient); }

.reading-text-box {
    background: rgba(10, 6, 22, 0.65);
    border: 1px solid rgba(223, 172, 108, 0.12);
    border-radius: var(--radius-md);
    padding: 20px;
    font-size: 0.92rem;
    line-height: 1.7;
    max-height: 320px;
    overflow-y: auto;
}

.reading-text-box h3 {
    font-family: var(--font-serif);
    color: var(--gold-primary);
    margin: 14px 0 8px 0;
    font-size: 1.05rem;
    border-bottom: 1px solid rgba(223, 172, 108, 0.15);
    padding-bottom: 4px;
}

.reading-text-box ul { margin-left: 18px; margin-bottom: 12px; }
.result-actions { display: flex; gap: 12px; }

.form-grid { display: flex; flex-direction: column; gap: 14px; }
.form-group { display: flex; flex-direction: column; gap: 6px; }
.form-group label { font-size: 0.85rem; color: var(--text-muted); }
.form-group input {
    background: rgba(10, 6, 22, 0.7);
    border: 1px solid rgba(223, 172, 108, 0.2);
    padding: 12px 16px;
    border-radius: var(--radius-sm);
    color: var(--soft-white);
    font-size: 0.92rem;
    outline: none;
    transition: var(--transition-smooth);
}

.kundli-chart-wrapper { display: flex; flex-direction: column; align-items: center; gap: 18px; }

.diamond-kundli {
    width: 250px;
    height: 250px;
    background: rgba(10, 6, 22, 0.85);
    border-radius: var(--radius-md);
    padding: 8px;
    border: 1px solid var(--gold-primary);
    box-shadow: inset 0 0 20px rgba(0, 0, 0, 0.8);
}

.kundli-svg { width: 100%; height: 100%; }

.kundli-analysis-text {
    background: rgba(10, 6, 22, 0.65);
    padding: 16px;
    border-radius: var(--radius-md);
    border: 1px solid rgba(223, 172, 108, 0.12);
    width: 100%;
    font-size: 0.9rem;
    line-height: 1.6;
}

.tarot-wrapper { align-items: center; }
.tarot-deck-container { display: flex; justify-content: center; gap: 16px; margin: 20px 0; flex-wrap: wrap; }
.tarot-card-item { width: 130px; height: 205px; perspective: 1000px; cursor: pointer; }
.tarot-card-inner {
    position: relative;
    width: 100%;
    height: 100%;
    transition: transform 0.8s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    transform-style: preserve-3d;
    border-radius: var(--radius-md);
}

.tarot-card-item.flipped .tarot-card-inner { transform: rotateY(180deg); }

.tarot-card-front, .tarot-card-back {
    position: absolute;
    width: 100%;
    height: 100%;
    backface-visibility: hidden;
    border-radius: var(--radius-md);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 12px;
    text-align: center;
}

.tarot-card-back {
    background: linear-gradient(135deg, #1D103A, #0D071B);
    border: 2px solid var(--gold-primary);
    color: var(--gold-primary);
    box-shadow: 0 8px 25px rgba(0, 0, 0, 0.6);
}

.tarot-card-front {
    background: linear-gradient(135deg, #180D33, #2B155B);
    border: 2px solid var(--gold-primary);
    color: var(--soft-white);
    transform: rotateY(180deg);
}

.num-badges-row { display: flex; gap: 16px; justify-content: center; }

.num-badge-card {
    background: rgba(10, 6, 22, 0.7);
    border: 1px solid rgba(223, 172, 108, 0.15);
    padding: 18px;
    border-radius: var(--radius-md);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
    flex: 1;
}

.num-circle {
    width: 65px;
    height: 65px;
    border-radius: 50%;
    background: linear-gradient(135deg, var(--velvet-violet), #4C1D95);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.8rem;
    font-weight: 700;
    color: #FFF;
}

.num-circle.gold {
    background: var(--gold-gradient);
    color: #0A0616;
}

.history-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(270px, 1fr));
    gap: 16px;
}

.history-item-card {
    background: rgba(10, 6, 22, 0.7);
    border: 1px solid rgba(223, 172, 108, 0.15);
    border-radius: var(--radius-md);
    padding: 16px;
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.app-footer {
    text-align: center;
    padding: 20px 0;
    margin-top: 24px;
    color: var(--text-muted);
    font-size: 0.82rem;
}

